create table public.menu_sets(id uuid primary key default gen_random_uuid(), name text not null, description text not null default '', price bigint not null check(price>0), dish_count int not null check(dish_count between 1 and 20), min_guests int not null default 30 check(min_guests>0), image_url text, active boolean not null default true, created_at timestamptz not null default now());
create table public.menu_categories(id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, created_at timestamptz not null default now());
create table public.dishes(id uuid primary key default gen_random_uuid(), name text not null, category_id uuid references public.menu_categories, description text not null default '', active boolean not null default true, created_at timestamptz not null default now());
create table public.drinks(id uuid primary key default gen_random_uuid(), name text not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.desserts(id uuid primary key default gen_random_uuid(), name text not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.add_ons(id uuid primary key default gen_random_uuid(), name text not null, price bigint not null check(price>=0), active boolean not null default true, created_at timestamptz not null default now());
create table public.event_setups(id uuid primary key default gen_random_uuid(), name text not null, price bigint not null check(price>=0), active boolean not null default true, created_at timestamptz not null default now());
create table public.event_features(id uuid primary key default gen_random_uuid(), name text not null, price bigint not null check(price>=0), active boolean not null default true, created_at timestamptz not null default now());
create table public.chair_types(id uuid primary key default gen_random_uuid(), name text not null, price bigint not null check(price>=0), active boolean not null default true, created_at timestamptz not null default now());
create table public.table_types(id uuid primary key default gen_random_uuid(), name text not null, price bigint not null default 0 check(price>=0), active boolean not null default true, created_at timestamptz not null default now());
